11	/*!
12	 * \file ai_infra_aggregate_hidden_tiling.cpp
13	 * \brief
14	 */
15	
16	#include "ai_infra_aggregate_hidden_tiling.h"
17	#include "log/log.h"
18	#include "err/ops_err.h"
19	
20	using namespace ge;
21	using namespace AscendC;
22	using std::map;
23	using std::string;
24	namespace optiling {
25	
26	static constexpr int64_t NUM_ZERO = 0;
27	static constexpr int64_t NUM_ONE = 1;
28	static constexpr int64_t NUM_TWO = 2;
29	static constexpr int64_t NUM_THREE = 3;
30	static constexpr int64_t NUM_FOUR = 4;
31	static constexpr int64_t NUM_FIVE = 5;
32	static constexpr int64_t NUM_SIX = 6;
33	static constexpr int64_t NUM_SEVEN = 7;
34	static constexpr int64_t NUM_EIGHT = 8;
35	static constexpr int64_t FOURTY = 40;
36	static constexpr int64_t FOURTY_EIGHT = 48;
37	
38	// ------------------算子原型索引常量定义----------------
39	// Inputs Index
40	static constexpr int64_t INPUT_INDEX = 0;
41	static constexpr int64_t WEIGHT_INDEX = 1;
42	static constexpr int64_t MASK_INDEX = 2;
43	
44	// Outputs Index
45	static constexpr int64_t OUTPUT_INDEXER = 0;
46	
47	// Dim Num
48	static constexpr int64_t DIM_NUM_TWO = 2;
49	static constexpr int64_t DIM_NUM_THREE = 3;
50	
51	// Dim Index
52	static constexpr int64_t DIM_IDX_ZERO = 0;
53	static constexpr int64_t DIM_IDX_ONE = 1;
54	static constexpr int64_t DIM_IDX_TWO = 2;
55	static constexpr int64_t DIM_IDX_THREE = 3;
56	
57	// 入参限制常量
58	static constexpr int64_t S_SIZE_LIMIT = 32 * 1024;  // 32K
59	static constexpr int64_t B_SIZE_LIMIT = 8;
60	static constexpr int64_t H_SIZE_UP_LIMIT = 24576;  // 192*128
61	static constexpr int64_t H_SIZE_DOWN_LIMIT = 384;  // 192*2
62	static constexpr int64_t W_SIZE_LIMIT = 3;         // 卷积的窗口固定是3
63	static constexpr int64_t H_SIZE_FULL = 4096;       // UB全载时，H最大是4096
64	
65	// workspace上预留100M
66	static constexpr int64_t DEFAULT_WORKSPACE_SIZE = 100 * 1024 * 1024;
67	
68	// --------------------------AHInfoParser类成员函数定义-------------------------------------
69	ge::graphStatus AHInfoParser::GetOpName()
70	{
71	    if (context_->GetNodeName() == nullptr) {
72	        OP_LOGE("AiInfraAggregateHidden", "opName got from TilingContext is nullptr");
73	        return ge::GRAPH_FAILED;
74	    }
75	    opName_ = context_->GetNodeName();
76	    return ge::GRAPH_SUCCESS;
77	}
78	
79	ge::graphStatus AHInfoParser::GetNpuInfo()
80	{
81	    platformInfo_ = context_->GetPlatformInfo();
82	    OP_CHECK_IF(platformInfo_ == nullptr, OP_LOGE(opName_, "GetPlatformInfo is nullptr."), return ge::GRAPH_FAILED);
83	
84	    auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfo_);
85	    aivNum_ = static_cast<int64_t>(ascendcPlatform.GetCoreNumAiv());
86	    uint32_t aicNum = ascendcPlatform.GetCoreNumAic();
87	    OP_CHECK_IF(aicNum == 0 || aivNum_ == 0, OP_LOGE(opName_, "num of core obtained is 0."), return GRAPH_FAILED);
88	    socVersion_ = ascendcPlatform.GetSocVersion();
89	    if ((socVersion_ != platform_ascendc::SocVersion::ASCEND910B) &&
90	        (socVersion_ != platform_ascendc::SocVersion::ASCEND910_93)) {
91	        OP_LOGE(opName_, "SOC Version[%d] is not support.", (int32_t)socVersion_);
92	        return GRAPH_FAILED;
93	    }
94	    OP_CHECK_IF(context_->GetWorkspaceSizes(1) == nullptr,
95	        OP_LOGE(opName_, "workSpaceSize got from ge is nullptr"),
96	        return ge::GRAPH_FAILED);
97	    OP_CHECK_IF(context_->GetRawTilingData() == nullptr,
98	        OP_LOGE(context_->GetNodeName(), "RawTilingData got from GE context is nullptr."),
99	        return ge::GRAPH_FAILED);
100	
101	    return ge::GRAPH_SUCCESS;
102	}
103	
104	ge::graphStatus AHInfoParser::CheckInputValid()
105	{
106	    // 1.获取变量相关参数
107	    opParamInfo_.input.desc = context_->GetInputDesc(INPUT_INDEX);
108	    opParamInfo_.input.shape = context_->GetInputShape(INPUT_INDEX);
109	    // 2.检查变量是否存在
110	    OP_CHECK_IF(opParamInfo_.input.shape == nullptr,
111	        OP_LOGE(opName_, "Shape of tensor input is nullptr"),
112	        return ge::GRAPH_FAILED);
113	    OP_CHECK_IF(opParamInfo_.input.desc == nullptr,
114	        OP_LOGE(opName_, "Desc of tensor input is nullptr"),
115	        return ge::GRAPH_FAILED);
116	    // 3.检查变量类型
117	    inputType_ = opParamInfo_.input.desc->GetDataType();
118	    OP_CHECK_IF(((inputType_ != ge::DT_FLOAT16) && (inputType_ != ge::DT_BF16)),
119	        OP_LOGE(opName_, "The data types of the input must be float16 or bfloat16."),
120	        return ge::GRAPH_FAILED);
121	    // 4.检查变量Shape的Dim
122	    int64_t inputShapeDim = opParamInfo_.input.shape->GetStorageShape().GetDimNum();
123	    int64_t inputExpectShapeDim = DIM_NUM_THREE;
124	    OP_CHECK_IF(inputShapeDim != inputExpectShapeDim,
125	        OP_LOGE(
126	            opName_, "the dim num of input's shape should be %u, but now is %u", inputExpectShapeDim, inputShapeDim),
127	        return ge::GRAPH_FAILED);
128	    // 5.检查变量shape大小是否超限 input [S,B,H],
129	    //  -----------------------check S Size-------------------
130	    sSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO));
131	    OP_LOGI(context_->GetNodeName(), "sSize is %d", sSize_);
132	    OP_CHECK_IF(sSize_ > S_SIZE_LIMIT,
133	        OP_LOGE(opName_, "the max of S size only support 32K, but now is %d.", sSize_),
134	        return ge::GRAPH_FAILED);
135	    // -----------------------check B Size-------------------
136	    bSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE));
137	    OP_LOGI(context_->GetNodeName(), "bSize is %d", bSize_);
138	    OP_CHECK_IF(bSize_ > B_SIZE_LIMIT,
139	        OP_LOGE(opName_, "the max of batch size only support 8, but now is %d.", bSize_),
140	        return ge::GRAPH_FAILED);
141	    // -----------------------check H Size-------------------
142	    hSize_ = static_cast<int64_t>(opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO));
143	    OP_LOGI(context_->GetNodeName(), "hSize is %d", hSize_);
144	    OP_CHECK_IF(hSize_ > H_SIZE_UP_LIMIT,
145	        OP_LOGE(opName_, "the max of H size must smaller than 24576, but now is %d.", hSize_),
146	        return ge::GRAPH_FAILED);
147	    OP_CHECK_IF(hSize_ < H_SIZE_DOWN_LIMIT,
148	        OP_LOGE(opName_, "the min of H size must larger than 384, but now is %d.", hSize_),
149	        return ge::GRAPH_FAILED);
150	
151	    return ge::GRAPH_SUCCESS;
152	}
153	
154	ge::graphStatus AHInfoParser::CheckWeightValid()
155	{
156	    // 1.获取变量相关参数
157	    opParamInfo_.weight.desc = context_->GetInputDesc(WEIGHT_INDEX);
158	    opParamInfo_.weight.shape = context_->GetInputShape(WEIGHT_INDEX);
159	    // 2.检查变量是否存在
160	    OP_CHECK_IF(opParamInfo_.weight.shape == nullptr,
161	        OP_LOGE(opName_, "Shape of tensor weight is nullptr"),
162	        return ge::GRAPH_FAILED);
163	    OP_CHECK_IF(opParamInfo_.weight.desc == nullptr,
164	        OP_LOGE(opName_, "Desc of tensor weight is nullptr"),
165	        return ge::GRAPH_FAILED);
166	    // 3.检查变量类型
167	    weightType_ = opParamInfo_.weight.desc->GetDataType();
168	    OP_CHECK_IF((inputType_ != weightType_),
169	        OP_LOGE(opName_, "The data types of the input and weight must be the same."),
170	        return ge::GRAPH_FAILED);
171	    // 4. 检查变量Shape的Dim
172	    int64_t weightShapeDim = opParamInfo_.weight.shape->GetStorageShape().GetDimNum();
173	    int64_t weightExpectShapeDim = DIM_NUM_TWO;
174	    OP_CHECK_IF(weightShapeDim != weightExpectShapeDim,
175	        OP_LOGE(
176	            opName_, "the dim num of weight's shape should be %u, but now is %u", weightExpectShapeDim, weightShapeDim),
177	        return ge::GRAPH_FAILED);
178	    // 5.检查变量shape大小是否超限,weight [W=3,H]
179	    //  -----------------------check W Size-------------------
180	    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != W_SIZE_LIMIT),
181	        OP_LOGE(opName_, "The window size of convolution must be 3."),
182	        return ge::GRAPH_FAILED);
183	    // 6.检查变量shape大小是否与input一致
184	    //  -----------------------check H Size-------------------
185	    OP_CHECK_IF((opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != hSize_),
186	        OP_LOGE(opName_,
187	            "Input dim 2 and Weight dim 1 is %u, %u respectively, they must be same.",
188	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
189	            opParamInfo_.weight.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
190	        return ge::GRAPH_FAILED);
191	
192	    return ge::GRAPH_SUCCESS;
193	}
194	
195	ge::graphStatus AHInfoParser::CheckMaskValid()
196	{
197	    // 1.获取变量相关参数
198	    opParamInfo_.mask.tensor = context_->GetOptionalInputTensor(MASK_INDEX);
199	    opParamInfo_.mask.desc = context_->GetOptionalInputDesc(MASK_INDEX);
200	    // 2.判断可选变量是否存在
201	    ifMask_ = 0;
202	    if (opParamInfo_.mask.tensor != nullptr) {
203	        ifMask_ = 1;
204	        // 3. 检查变量类型
205	        OP_CHECK_IF(opParamInfo_.mask.desc->GetDataType() != ge::DT_BOOL,
206	            OP_LOGE(opName_, "the mask data type only support BOOL"),
207	            return ge::GRAPH_FAILED);
208	        // 4. 检查变量Shape的Dim
209	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDimNum() != DIM_NUM_TWO),
210	            OP_LOGE(opName_, "the dim num of mask's shape should be 2"),
211	            return ge::GRAPH_FAILED);
212	        // 5.检查变量shape大小是否与input一致,mask [B,S]
213	        //  -----------------------check B Size-------------------
214	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO) != bSize_),
215	            OP_LOGE(opName_,
216	                "Input dim 1 and mask dim 0 is %u, %u respectively, they must be same.",
217	                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
218	                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ZERO)),
219	            return ge::GRAPH_FAILED);
220	        // -----------------------check S Size-------------------
221	        OP_CHECK_IF((opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE) != sSize_),
222	            OP_LOGE(opName_,
223	                "Input dim 0 and mask dim 1 is %u, %u respectively, they must be same.",
224	                opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
225	                opParamInfo_.mask.tensor->GetStorageShape().GetDim(DIM_IDX_ONE)),
226	            return ge::GRAPH_FAILED);
227	    }
228	
229	    return ge::GRAPH_SUCCESS;
230	}
231	
232	ge::graphStatus AHInfoParser::CheckOutputValid()
233	{
234	    // 1.获取变量相关参数
235	    opParamInfo_.output.desc = context_->GetOutputDesc(OUTPUT_INDEXER);
236	    opParamInfo_.output.shape = context_->GetOutputShape(OUTPUT_INDEXER);
237	    // 2.检查变量是否存在
238	    OP_CHECK_IF(opParamInfo_.output.shape == nullptr,
239	        OP_LOGE(opName_, "Shape of tensor output is nullptr"),
240	        return ge::GRAPH_FAILED);
241	    OP_CHECK_IF(opParamInfo_.output.desc == nullptr,
242	        OP_LOGE(opName_, "Desc of tensor output is nullptr"),
243	        return ge::GRAPH_FAILED);
244	    // 3.检查变量类型
245	    outputType_ = opParamInfo_.output.desc->GetDataType();
246	    OP_CHECK_IF((inputType_ != outputType_),
247	        OP_LOGE(opName_, "The data types of the input and output must be the same."),
248	        return ge::GRAPH_FAILED);
249	    // 4. 检查变量Shape的Dim
250	    int64_t outputShapeDim = opParamInfo_.output.shape->GetStorageShape().GetDimNum();
251	    int64_t outputExpectShapeDim = DIM_NUM_THREE;
252	    OP_CHECK_IF(outputShapeDim != outputExpectShapeDim,
253	        OP_LOGE(
254	            opName_, "the dim num of output's shape should be %u, but now is %u", outputExpectShapeDim, outputShapeDim),
255	        return ge::GRAPH_FAILED);
256	    // 5.检查变量shape大小是否与input一致, output [S,B,H]
257	    //  -----------------------check S Size-------------------
258	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO) != sSize_),
259	        OP_LOGE(opName_,
260	            "Input and Output dim 0 is %u, %u respectively, they must be same.",
261	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ZERO),
262	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ZERO)),
263	        return ge::GRAPH_FAILED);
264	    // -----------------------check B Size-------------------
265	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE) != bSize_),
266	        OP_LOGE(opName_,
267	            "Input and Output dim 1 is %u, %u respectively, they must be same.",
268	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_ONE),
269	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_ONE)),
270	        return ge::GRAPH_FAILED);
271	    // -----------------------check H Size-------------------
272	    OP_CHECK_IF((opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO) != hSize_),
273	        OP_LOGE(opName_,
274	            "Input dim 2 and Output dim 2 is %u, %u respectively, they must be same.",
275	            opParamInfo_.input.shape->GetStorageShape().GetDim(DIM_IDX_TWO),
276	            opParamInfo_.output.shape->GetStorageShape().GetDim(DIM_IDX_TWO)),
277	        return ge::GRAPH_FAILED);
278	
279	    return ge::GRAPH_SUCCESS;
280	}
281	
282	ge::graphStatus AHInfoParser::GetTilingKey()  // 根据输入数据的类型区分tiling key
283	{
284	    tilingKey_ = AGGREGATE_HIDDEN_BF16;
285	    if (inputType_ == ge::DT_FLOAT16) {
286	        tilingKey_ = AGGREGATE_HIDDEN_HALF;
287	    }
288	    return ge::GRAPH_SUCCESS;
289	}
290	
291	ge::graphStatus AHInfoParser::CoreSplit()  // 分核计算,如果H能全载就不切H
292	{
293	    baseHCnt_ = (hSize_ + H_SIZE_FULL - NUM_ONE) /
294	                H_SIZE_FULL;  // H切分的份数 = hSize_/4096取上整 baseHCnt_表示一整份H需要用几个核处理
295	    int64_t flagChange = NUM_ZERO;
296	    // 调整baseHCnt_使得它能整除aivNum_
297	    // aivNum_ == 48 | baseHCnt_ == 5
298	    if (aivNum_ == FOURTY_EIGHT && baseHCnt_ == NUM_FIVE) {
299	        baseHCnt_ = NUM_SIX;
300	        flagChange = NUM_ONE;
301	    }
302	    // conditions are independent
303	    // aivNum_ == 40 | baseHCnt_ == 6
304	    if (aivNum_ == FOURTY && baseHCnt_ == NUM_SIX) {
305	        baseHCnt_ = NUM_EIGHT;
306	        flagChange = NUM_ONE;
307	    }
308	    // aivNum_ == 40 | baseHCnt_ == 3
309	    if (aivNum_ == FOURTY && baseHCnt_ == NUM_THREE) {
310	        baseHCnt_ = NUM_FOUR;
311	        flagChange = NUM_ONE;
312	    }
313	    // else, no assignment
314	
315	    // 计算baseH_
316	    if (hSize_ <= H_SIZE_FULL) {
317	        baseH_ = hSize_;
318	        baseHTail_ = baseH_;
319	    } else {
320	        baseH_ = H_SIZE_FULL;  // baseHCnt_没有被额外修改
321	        baseHTail_ = hSize_ % baseH_ == NUM_ZERO ? baseH_ : hSize_ % baseH_;
322	        if (flagChange == NUM_ONE) {  // baseHCnt_被额外修改
323	            baseH_ = hSize_ / baseHCnt_;
324	            baseHTail_ = hSize_ % baseHCnt_ == NUM_ZERO ? baseH_ : hSize_ - (baseH_ * (baseHCnt_ - NUM_ONE));
325	        }
326	    }
327	
328	    // 计算baseB_
329	    int64_t coreNumH = aivNum_ / baseHCnt_;  // coreNumH 表示B还能切多少个核
330	    baseB_ = (bSize_ + coreNumH - NUM_ONE) / coreNumH;
331	    if (bSize_ % baseB_ == NUM_ZERO) {
332	        baseBTail_ = baseB_;
333	    } else {
334	        baseBTail_ = bSize_ % baseB_;
335	    }
336	    // 计算baseS_
337	    // 默认不切S
338	    baseS_ = sSize_;
339	    baseSTail_ = baseS_;
340	    baseSCnt_ = NUM_ONE;      // 1表示不切S
341	    if (baseB_ == NUM_ONE) {  // baseB_大于1，表示B没切完，不切S
342	        baseSCnt_ = coreNumH / bSize_;
343	        baseS_ = baseSCnt_ > sSize_ ? NUM_ONE : (sSize_ + baseSCnt_ - NUM_ONE) / baseSCnt_;
344	        baseSCnt_ = baseSCnt_ > sSize_ ? sSize_ : (sSize_ + baseS_ - 1) / baseS_;
345	        baseSTail_ = sSize_ % baseSCnt_ == NUM_ZERO ? baseS_ : sSize_ - (baseS_ * (baseSCnt_ - NUM_ONE));
346	    }
347	
348	    // 计算blockDim
349	    baseBCnt_ = (bSize_ + baseB_ - NUM_ONE) / baseB_;
350	    blockDim_ = baseHCnt_ * baseBCnt_ * baseSCnt_;
351	
352	    return ge::GRAPH_SUCCESS;
353	}
