// 用例1: BF16 无Mask
TEST_F(AiInfraAggregateHiddenTiling, ai_infra_aggregate_hidden_bf16_4096_4_768_noMask_pangu_000000)
{
    int64_t S = 4096;
    int64_t B = 4;
    int64_t H = 768;
    int64_t W = 3;

    optiling::AiInfraAggregateHiddenCompileInfo compileInfo = {};

    gert::TilingContextPara tilingContextPara(
        "AiInfraAggregateHidden",
        {
            {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND},
            {{{W, H}, {W, H}}, ge::DT_BF16, ge::FORMAT_ND},
        },
        {
            {{{S, B, H}, {S, B, H}}, ge::DT_BF16, ge::FORMAT_ND},
